import{_ as a,o as t,c as s,ai as i}from"./chunks/framework.Ci0kozOl.js";const u=JSON.parse(`{"title":"What's New in the v3.0 API","description":"","frontmatter":{},"headers":[],"relativePath":"3.0/api/whats-new-v3.md","filePath":"3.0/api/whats-new-v3.md","lastUpdated":1786019473000}`),o={name:"3.0/api/whats-new-v3.md"};function n(d,e,r,c,p,l){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="what-s-new-in-the-v3-0-api" tabindex="-1">What&#39;s New in the v3.0 API <a class="header-anchor" href="#what-s-new-in-the-v3-0-api" aria-label="Permalink to &quot;What&#39;s New in the v3.0 API&quot;">​</a></h1><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h2><p>UnoPim 3.0 substantially expands the REST API. Resources that were previously read-only can now be written, media files can be read and deleted, products support incremental synchronization, and API integrations run under a new authentication model.</p><p>If you are building or maintaining an API client, this page is your tour of everything that changed. Every endpoint lives under <code>/api/v1/rest/</code>, authenticates with OAuth 2.0 (password grant), and requires an <code>Accept: application/json</code> header.</p><p>We will start with the new write operations and media endpoints, move on to delta synchronization, and finish with the authentication changes and a deprecation you should plan for.</p><h2 id="new-write-operations" tabindex="-1">New Write Operations <a class="header-anchor" href="#new-write-operations" aria-label="Permalink to &quot;New Write Operations&quot;">​</a></h2><p>Catalog-structure resources gained the verbs they were missing. The table below lists each resource and the operations added in 3.0:</p><table tabindex="0"><thead><tr><th>Resource</th><th>New in 3.0</th></tr></thead><tbody><tr><td><code>attributes</code></td><td><code>PATCH /attributes/{code}</code>, <code>DELETE /attributes/{code}</code>, <code>DELETE /attributes/{code}/options/{optionCode}</code></td></tr><tr><td><code>attribute-groups</code></td><td><code>PATCH</code>, <code>DELETE</code></td></tr><tr><td><code>families</code></td><td><code>PATCH</code>, <code>DELETE</code></td></tr><tr><td><code>category-fields</code></td><td><code>PATCH</code>, <code>DELETE</code>, <code>DELETE .../options/{optionCode}</code></td></tr><tr><td><code>locales</code></td><td><code>POST</code>, <code>PUT</code>, <code>DELETE</code> (previously read-only)</td></tr><tr><td><code>channels</code></td><td><code>POST</code>, <code>PUT</code>, <code>DELETE</code></td></tr><tr><td><code>currencies</code></td><td><code>POST</code>, <code>PUT</code>, <code>DELETE</code></td></tr></tbody></table><p><code>PATCH</code> performs a partial update — only the keys you submit will change. Locale, channel, and currency writes apply the same in-use and default-record guards as the admin panel, so you cannot delete a channel&#39;s default locale over the API.</p><h2 id="media-endpoints" tabindex="-1">Media Endpoints <a class="header-anchor" href="#media-endpoints" aria-label="Permalink to &quot;Media Endpoints&quot;">​</a></h2><p>Product, category, and swatch media now support read and delete alongside upload. Media files are identified by query parameters rather than path segments:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET    /api/v1/rest/media-files/product?sku=shirt-1&amp;attribute=image</span></span>
<span class="line"><span>DELETE /api/v1/rest/media-files/product?sku=shirt-1&amp;attribute=image</span></span>
<span class="line"><span>GET    /api/v1/rest/media-files/category?code=apparel&amp;category_field=banner</span></span>
<span class="line"><span>GET    /api/v1/rest/media-files/swatch?code=red&amp;attribute_code=color</span></span></code></pre></div><h2 id="digital-product-passports" tabindex="-1">Digital Product Passports <a class="header-anchor" href="#digital-product-passports" aria-label="Permalink to &quot;Digital Product Passports&quot;">​</a></h2><p>Passports are fully manageable over the API under <code>/api/v1/rest/passports</code> — you may list them, read them per SKU, publish (the endpoint returns <code>202</code> and queues the work), withdraw, reinstate, and perform a GDPR redact. See <a href="./../advanced/digital-product-passport.html#rest-api">Digital Product Passport</a>.</p><h2 id="measurements" tabindex="-1">Measurements <a class="header-anchor" href="#measurements" aria-label="Permalink to &quot;Measurements&quot;">​</a></h2><p>Measurement families, units, and attribute bindings are fully manageable over the API — see <a href="./../packages/measurements.html#rest-api">Measurements</a>.</p><h2 id="delta-synchronization" tabindex="-1">Delta Synchronization <a class="header-anchor" href="#delta-synchronization" aria-label="Permalink to &quot;Delta Synchronization&quot;">​</a></h2><p>Sometimes you may wish to sync only the products that changed since your last run rather than paging through the entire catalog. Products now support exactly that, combining date filters with cursor pagination:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /api/v1/rest/products</span></span>
<span class="line"><span>    ?filters={&quot;updated_at&quot;:[{&quot;operator&quot;:&quot;&gt;=&quot;,&quot;value&quot;:&quot;2026-08-01 00:00:00&quot;}]}</span></span>
<span class="line"><span>    &amp;pagination_type=search_after</span></span>
<span class="line"><span>    &amp;limit=100</span></span></code></pre></div><p>Date filters on <code>created_at</code> / <code>updated_at</code> support the <code>&gt;</code>, <code>&gt;=</code>, <code>&lt;</code>, <code>&lt;=</code>, and <code>BETWEEN</code> operators (<code>BETWEEN</code> requires exactly two values), and multiple filters combine with AND.</p><p>Cursor pagination (<code>pagination_type=search_after</code>) avoids the <code>COUNT(*)</code> and deep-offset costs of page mode. Each response returns the cursor for the next page:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;data&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [ </span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">...</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;search_after&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1234</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;links&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;next&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;...?pagination_type=search_after&amp;search_after=1234&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>When <code>search_after</code> comes back as <code>null</code>, there are no more pages. The <code>limit</code> parameter is clamped to 1–100 and defaults to 10.</p><p>Two further features make repeated polling cheap. Responses carry an <code>ETag</code>, so you may send <code>If-None-Match</code> and receive <code>304 Not Modified</code> — skipping re-processing of unchanged data entirely. And slow-changing resources (attributes, groups, families, category fields, locales, channels, currencies) are served from a versioned server-side structure cache that invalidates automatically on writes and import completion; it is controlled by <code>UNOPIM_API_STRUCTURE_CACHE</code> and the TTL by <code>UNOPIM_API_STRUCTURE_CACHE_TTL</code>.</p><h2 id="robot-users-and-authentication" tabindex="-1">Robot Users and Authentication <a class="header-anchor" href="#robot-users-and-authentication" aria-label="Permalink to &quot;Robot Users and Authentication&quot;">​</a></h2><p>API integrations now run as dedicated <strong>robot users</strong>. When you create an integration, UnoPim will automatically provision a least-privilege <code>type = &#39;api&#39;</code> admin, and the credentials are revealed exactly once. Integration creation no longer accepts <code>admin_id</code> — existing integrations were migrated automatically. If you lose the credentials, you may recover access by regenerating the password or client secret from the integration edit screen; both actions revoke existing tokens.</p><div class="warning custom-block"><p class="custom-block-title">Token invalidation on upgrade</p><p>v3.0 replaces the previously shared OAuth signing keys with per-installation 4096-bit keys. All tokens issued before the upgrade are invalid — authenticate again.</p></div><p>Rate limits are configurable: <code>REST_API_RATE_LIMIT</code> (default 120/min) applies to all endpoints, and <code>OAUTH_TOKEN_RATE_LIMIT</code> (default 10/min) applies to token issue and refresh. Token lifetimes are controlled by <code>ACCESS_TOKEN_TTL</code> and <code>REFRESH_TOKEN_TTL</code> (default 3600 seconds).</p><h2 id="deprecated-alias" tabindex="-1">Deprecated Alias <a class="header-anchor" href="#deprecated-alias" aria-label="Permalink to &quot;Deprecated Alias&quot;">​</a></h2><p>The misspelled <code>configrable-products</code> prefix still works, but it now returns RFC 8594 deprecation headers:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Deprecation: true</span></span>
<span class="line"><span>Link: &lt;/api/v1/rest/configurable-products&gt;; rel=&quot;successor-version&quot;</span></span></code></pre></div><p>You should migrate your clients to <code>configurable-products</code> — the alias will be removed in a future release.</p>`,32)])])}const g=a(o,[["render",n]]);export{u as __pageData,g as default};
